INSERT INTO `categories` VALUES (1,'North of Vietnam','North-of-Vietnam','It is a political center and a vast area with a long-standing history and numerous tourist attractions that help visitors gain a deeper understanding of Vietnam\'s history.','2026-10-08 15:43:58','2026-10-08 15:44:00'),(2,'Central Region of Vietnam','Central-Region-of-Vietnam','It is an area with an extensive coastline and beautiful seascapes, best known for its beaches featuring modern amenities.','2026-10-08 15:46:27','2026-10-08 15:46:29'),(3,'South of VietNam','South-of-Vietnam','As the country\'s largest economic hub, it features a wide range of modern tourist areas and diverse entertainment infrastructure.','2026-10-08 15:49:26','2026-10-08 15:49:28');
